import * as T from './assets/three.module.js';
import {surfaceHeight} from './expedition-math.js';
export function makeRover(){
 const g=new T.Group(),white=new T.MeshStandardMaterial({color:0xd8d5c9,roughness:.43,metalness:.55}),gold=new T.MeshStandardMaterial({color:0xb79752,metalness:.7,roughness:.3}),black=new T.MeshStandardMaterial({color:0x1b242c,roughness:.9}),glass=new T.MeshStandardMaterial({color:0x173c57,metalness:.7,roughness:.1});
 const part=(geometry,material,x,y,z)=>{const m=new T.Mesh(geometry,material);m.position.set(x,y,z);g.add(m);return m;};
 part(new T.BoxGeometry(.7,.18,.55),white,0,.38,0);part(new T.BoxGeometry(.42,.18,.36),gold,0,.54,0);for(const x of [-.38,.38])for(const z of [-.33,0,.33]){const w=part(new T.CylinderGeometry(.16,.16,.14,24),black,x,.17,z);w.rotation.z=Math.PI/2;for(let k=0;k<12;k++){const tread=part(new T.BoxGeometry(.15,.025,.035),white,x,.17+Math.cos(k/12*Math.PI*2)*.16,z+Math.sin(k/12*Math.PI*2)*.16);tread.rotation.x=-k/12*Math.PI*2;}const arm=part(new T.CylinderGeometry(.018,.018,.43,8),white,x*.8,.28,z*.8);arm.rotation.z=x>0?-.5:.5;}
 part(new T.CylinderGeometry(.025,.035,.7,12),white,.12,.92,-.05);part(new T.BoxGeometry(.24,.10,.11),white,.12,1.25,-.05);for(const x of [.05,.19])part(new T.CylinderGeometry(.036,.036,.03,16),glass,x,1.25,-.12).rotation.x=Math.PI/2;
 const antenna=part(new T.SphereGeometry(.15,24,12,0,Math.PI*2,0,Math.PI/2),white,-.17,.75,.12);antenna.rotation.z=.4;part(new T.CylinderGeometry(.006,.006,.24,8),gold,-.17,.94,.12);
 const solar=part(new T.BoxGeometry(.8,.015,.65),glass,0,.67,.07);solar.rotation.z=.1;for(let j=0;j<8;j++)part(new T.BoxGeometry(.78,.018,.003),white,0,.68,-.22+j*.085);
 const headlight=new T.SpotLight(0xe5efff,4,10,.5,.4,1.5);headlight.position.set(0,.5,-.3);headlight.target.position.set(0,0,-6);g.add(headlight,headlight.target);headlight.name='rover-headlight';
 g.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});return g;
}
export function decorateSurface(group,terrain,seed){
 const random=i=>{const t=Math.sin(i*127.1+seed)*43758.5453;return t-Math.floor(t)};
 terrain.receiveShadow=true;const rocks=new T.InstancedMesh(new T.DodecahedronGeometry(1,1),new T.MeshStandardMaterial({color:0x6e6e64,roughness:.98}),220),matrix=new T.Matrix4();rocks.castShadow=true;rocks.receiveShadow=true;for(let i=0;i<220;i++){const x=(random(i+1)-.5)*30,z=(random(i+600)-.5)*30,s=.04+random(i+201)*.25;matrix.compose(new T.Vector3(x,surfaceHeight(x,z,seed)+s*.25,z),new T.Quaternion().setFromEuler(new T.Euler(i,random(i+40),i*.3)),new T.Vector3(s,s*.6,s*.8));rocks.setMatrixAt(i,matrix)}group.add(rocks);
 const positions=new Float32Array(96*6),lidar=new T.LineSegments(new T.BufferGeometry().setAttribute('position',new T.BufferAttribute(positions,3)),new T.LineBasicMaterial({color:0x8bd4c5,transparent:true,opacity:.45,depthWrite:false}));group.add(lidar);
 const trackGeo=new T.BufferGeometry().setAttribute('position',new T.BufferAttribute(new Float32Array(1500*3),3)),tracks=new T.Line(trackGeo,new T.LineBasicMaterial({color:0x3d3933,transparent:true,opacity:.75}));trackGeo.setDrawRange(0,0);group.add(tracks);let count=0,last=new T.Vector3(999,999,999);
 return {update(rover,time,{scan=false,showRocks=true,showTracks=true,headlight=false}={}){rocks.visible=showRocks;tracks.visible=showTracks;lidar.visible=scan;rover.getObjectByName('rover-headlight').visible=headlight;if(scan){const a=lidar.geometry.attributes.position;for(let i=0;i<96;i++){const angle=i/96*Math.PI*2+time*.3,r=2+(i%7)*.5,x=rover.position.x+Math.cos(angle)*r,z=rover.position.z+Math.sin(angle)*r;a.setXYZ(i*2,rover.position.x,rover.position.y+1.25,rover.position.z);a.setXYZ(i*2+1,x,surfaceHeight(x,z,seed)+.03,z);}a.needsUpdate=true;}if(rover.position.distanceTo(last)>.15&&count<1500){trackGeo.attributes.position.setXYZ(count++,rover.position.x,rover.position.y+.015,rover.position.z);trackGeo.attributes.position.needsUpdate=true;trackGeo.setDrawRange(0,count);last.copy(rover.position);}}};
}
